// System exceptions (from System namespace)

// NullReferenceException
// Accessing member on null object
string s = null;
Console.WriteLine(s.Length); // CRASH!

// IndexOutOfRangeException
// Accessing invalid array index
int[] nums = { 1, 2, 3 };
Console.WriteLine(nums[5]); // CRASH!

// ArgumentException
// Invalid argument passed
public void SetAge(int age)
{
    if (age < 0) throw new ArgumentException("Age cannot be negative");
}

// InvalidOperationException
// Method call invalid for object state
var list = new List<int>();
list.RemoveAt(0); // CRASH! - list is empty
